const lines = [];
const orig = process.stdout.write.bind(process.stdout);
process.stdout.write = (s) => { lines.push(String(s)); return true; };
try { require('./log.cjs').info('cafe-ready'); } finally { process.stdout.write = orig; }
const out = lines.join('');
if (!/cafe-ready/.test(out) || !/\d{2}:\d{2}:\d{2}/.test(out)) { console.error('bad output', JSON.stringify(out)); process.exit(1); }
